script:
(function () {
  'use strict';
  // After-tax cost of loan or credit line interest, deductible vs not deductible.
  //   Schedule: monthly interest = balance x APR / 12 (rounded to the cent); fixed payments use
  //     P = A x i / (1 - (1 + i)^-n) (A / n at 0%), interest-only keeps the balance.
  //   Deductible interest per year, by use of the money:
  //     home (secured by a qualified home, used to buy, build or substantially improve it):
  //       interest x min(1, limit / (other home debt + this loan's average balance that year)),
  //       the Pub. 936 Part II ratio of the debt limit to average home debt;
  //     home used for anything else, or unsecured personal spending: 0;
  //     investment interest: min(interest, net investment income) (excess carries forward,
  //       which this estimate ignores).
  //   Federal saving: "already itemize" -> bracket x deductible; "compare" -> bracket x
  //     (max(other + deductible, standard) - max(other, standard)), i.e. only the part that
  //     lifts itemized deductions above the standard deduction counts.
  //   State saving: state rate x deductible, only when itemizing beats the standard deduction
  //     (assumes the state allows the same deduction and follows the federal choice).
  //   Effective after-tax rate (year 1) = APR x (1 - year-1 savings / year-1 interest).
  // Verified (scratchpad b6credit/tx.test.js): $50,000 at 8.5% over 10 years -> $619.93/mo
  //   (closed form); year-1 interest equals the sum of the first 12 rows of an independent
  //   amortization; at 22% + 5% with "already itemize" and full deductibility the saving is
  //   27% of the interest; MFJ with $30,000 other deductions only the part above $32,200
  //   counts and the state saving is 0 when the standard deduction wins; other home debt $740,000 + $50,000 loan -> deductible share 750/(740 + avg);
  //   investment use with $3,000 NII caps the deduction at $3,000; non-deductible uses save $0.

  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) ----------------------------------------------
  // Standard deduction: IRS Rev. Proc. 2025-32 (as amended by P.L. 119-21).
  // Home mortgage debt limit $750,000 ($375,000 married filing separately) and the rule that
  //   home equity interest is deductible only when the proceeds buy, build or substantially
  //   improve the home securing the loan: IRS Pub. 936; the limit was made permanent by
  //   P.L. 119-21. Investment interest limited to net investment income: IRC 163(d), Form 4952.
  var TAX_YEAR = 2026;
  var STANDARD_DEDUCTION = { single: 16100, mfj: 32200, mfs: 16100, hoh: 24150 };
  var HOME_DEBT_LIMIT = { single: 750000, mfj: 750000, mfs: 375000, hoh: 750000 };

  // ---- Calculation ----
  function cents(x) { return Math.round(x * 100) / 100; }

  function payment(amount, apr, months) {
    var i = apr / 12;
    if (i === 0) return amount / months;
    return amount * i / (1 - Math.pow(1 + i, -months));
  }

  // Yearly rows: { interest, avgBalance, endBalance, paid }.
  function yearly(amount, apr, years, interestOnly) {
    var months = years * 12, P = payment(amount, apr, months), bal = amount, rows = [];
    for (var y = 0; y < years; y++) {
      var r = { interest: 0, avgBalance: 0, endBalance: 0, paid: 0 };
      for (var k = 1; k <= 12; k++) {
        var m = y * 12 + k;
        r.avgBalance += bal / 12;
        var interest = cents(bal * apr / 12);
        var pay = interestOnly ? interest : (m === months ? bal + interest : Math.min(cents(P), bal + interest));
        bal = cents(bal + interest - pay);
        if (bal < 0.005) bal = 0;
        r.interest += interest; r.paid += pay;
      }
      r.endBalance = bal;
      rows.push(r);
    }
    return { rows: rows, payment: interestOnly ? cents(amount * apr / 12) : P };
  }

  function deductibleShare(row, x) {
    if (x.use === 'home') {
      var limit = HOME_DEBT_LIMIT[x.status];
      var total = x.otherMortgage + row.avgBalance;
      return total <= limit ? row.interest : row.interest * Math.max(0, limit / total);
    }
    if (x.use === 'invest') return Math.min(row.interest, x.nii);
    return 0;
  }

  function taxSavings(x) {
    var sched = yearly(x.amount, x.apr, x.years, x.interestOnly);
    var std = STANDARD_DEDUCTION[x.status];
    var out = sched.rows.map(function (row) {
      var d = deductibleShare(row, x);
      var fedBase = x.itemize === 'yes' ? d : Math.max(x.otherItemized + d, std) - Math.max(x.otherItemized, std);
      var itemizes = x.itemize === 'yes' || x.otherItemized + d > std;
      var fed = x.fedRate * fedBase, state = itemizes ? x.stateRate * d : 0;
      return { interest: row.interest, deductible: d, fed: fed, state: state, after: row.interest - fed - state, endBalance: row.endBalance };
    });
    var t = out.reduce(function (s, r) {
      s.interest += r.interest; s.deductible += r.deductible; s.fed += r.fed; s.state += r.state; return s;
    }, { interest: 0, deductible: 0, fed: 0, state: 0 });
    return { rows: out, totals: t, payment: sched.payment };
  }

  // ---- UI ----
  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  function num(id) { var v = parseFloat(document.getElementById(id).value); return isNaN(v) ? NaN : v; }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearBody(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function clearResults() {
    ['ltsSavings', 'ltsAfter', 'ltsEffRate', 'ltsPayment'].forEach(function (id) { set(id, '–'); });
    ['ltsSavingsNote', 'ltsAfterNote', 'ltsEffNote'].forEach(function (id) { set(id, ''); });
    document.getElementById('ltsVerdict').hidden = true;
    clearBody('ltsSchedule');
  }

  function update() {
    var use = document.getElementById('ltsUse').value, itemize = document.getElementById('ltsItemize').value;
    var status = document.getElementById('ltsStatus').value;
    document.getElementById('ltsHomeWrap').hidden = use !== 'home';
    document.getElementById('ltsInvestWrap').hidden = use !== 'invest';
    document.getElementById('ltsOtherWrap').hidden = itemize !== 'compare';
    set('ltsOtherHint', 'Mortgage interest on your other home debt, state and local taxes (after the cap) and gifts to charity. Your ' + TAX_YEAR +
      ' standard deduction is ' + money.format(STANDARD_DEDUCTION[status]).replace('.00', '') + '.');
    var x = {
      amount: num('ltsAmount'), apr: num('ltsRate') / 100, years: Math.round(num('ltsYears')),
      interestOnly: document.getElementById('ltsRepay').value === 'interest', use: use, status: status, itemize: itemize,
      otherMortgage: use === 'home' ? num('ltsOtherMortgage') : 0, nii: use === 'invest' ? num('ltsNii') : 0,
      fedRate: parseFloat(document.getElementById('ltsFederal').value) / 100, stateRate: num('ltsState') / 100,
      otherItemized: itemize === 'compare' ? num('ltsOtherItemized') : 0
    };
    var error = document.getElementById('ltsError'), problem = '';
    if (isNaN(x.amount) || x.amount <= 0 || x.amount > 1e8) problem = 'Enter an amount borrowed above $0.';
    else if (isNaN(x.apr) || x.apr < 0 || x.apr > 1) problem = 'Enter an interest rate from 0 to 100%.';
    else if (isNaN(x.years) || x.years < 1 || x.years > 30) problem = 'Enter a period from 1 to 30 years.';
    else if (isNaN(x.otherMortgage) || x.otherMortgage < 0 || isNaN(x.nii) || x.nii < 0 || isNaN(x.otherItemized) || x.otherItemized < 0) problem = 'Enter amounts of $0 or more.';
    else if (isNaN(x.stateRate) || x.stateRate < 0 || x.stateRate > 0.2) problem = 'Enter a state tax rate from 0 to 20%.';
    if (problem) { error.hidden = false; error.textContent = problem; clearResults(); return; }
    error.hidden = true; error.textContent = '';

    var r = taxSavings(x), t = r.totals, saved = t.fed + t.state, y1 = r.rows[0];
    set('ltsSavings', money.format(saved));
    set('ltsSavingsNote', 'Federal ' + money.format(t.fed) + ', state ' + money.format(t.state) + ' over ' + x.years + (x.years === 1 ? ' year.' : ' years.'));
    set('ltsAfter', money.format(t.interest - saved));
    set('ltsAfterNote', 'If none were deductible: ' + money.format(t.interest) + '.');
    var eff = y1.interest > 0 ? x.apr * (1 - (y1.fed + y1.state) / y1.interest) : 0;
    set('ltsEffRate', (eff * 100).toFixed(2) + '%');
    set('ltsEffNote', 'In year 1, vs the ' + (x.apr * 100).toFixed(2) + '% APR.');
    set('ltsPayment', money.format(r.payment) + '/mo');

    var box = document.getElementById('ltsVerdict'), title, text;
    box.hidden = false;
    if (use === 'homeOther' || use === 'personal') {
      box.className = 'callout callout-warning mt-5';
      title = 'This interest is not deductible';
      text = use === 'homeOther'
        ? 'Interest on home equity debt is deductible only when the money buys, builds or substantially improves the home that secures it. Spent on anything else, you pay the full interest.'
        : 'Interest on personal loans and credit cards used for personal spending is not deductible, so the after-tax cost is the full interest.';
    } else if (saved < 0.005) {
      box.className = 'callout callout-caution mt-5';
      title = 'No tax saving at these figures';
      text = x.itemize === 'compare' && x.otherItemized + y1.deductible <= STANDARD_DEDUCTION[x.status]
        ? 'Your itemized deductions, including this interest, stay below the standard deduction, so taking the standard deduction is better and the interest saves nothing.'
        : 'None of the interest is deductible at these figures.';
    } else {
      box.className = 'callout callout-success mt-5';
      title = 'The deduction saves ' + money.format(saved);
      text = 'That is ' + Math.round(saved / t.interest * 100) + '% of the interest you pay. ' +
        (x.itemize === 'compare' ? 'Only the part of the interest that lifts your itemized deductions above the standard deduction saves federal tax. ' : '') +
        'Keep records showing how the money was used.';
    }
    set('ltsVerdictTitle', title);
    set('ltsVerdictText', text);

    var body = clearBody('ltsSchedule');
    r.rows.forEach(function (row, k) {
      var tr = document.createElement('tr');
      [String(k + 1), money.format(row.interest), money.format(row.deductible), money.format(row.fed), money.format(row.state),
        money.format(row.after), money.format(row.endBalance)].forEach(function (t2) {
        var td = document.createElement('td'); td.textContent = t2; tr.appendChild(td);
      });
      body.appendChild(tr);
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('ltsForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
